document.addEventListener('change',e=>{const el=e.target;if(el.dataset.scenePhoto)sceneLoadPhoto(el.files?.[0],el.dataset.scenePhoto);if(el.id==='scene-engine'){SCENE.engine=el.value==='local'||(typeof location!=='undefined'&&location.protocol==='file:')?'local':'online';SCENE.textConsent=false;SCENE.imageConsent=false;sceneSync();}if(el.id==='scene-text-consent'){SCENE.textConsent=el.checked;sceneSync();}if(el.id==='scene-image-consent'){SCENE.imageConsent=el.checked;sceneSync();}if(el.id==='scene-existing-photo'){const p=S.pool.find(p=>p.id===el.value);if(p&&SceneTools.imageSafe(p.dataUrl)){SCENE.look.photo={url:p.dataUrl,width:p.width||600,height:p.height||800,name:p.name};sceneDirty('look');paintScene();}}if(el.id==='scene-decision-art'){sceneSelectArt(el.value);sceneUpdateDecision();}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el||!el.dataset.act.startsWith('scene-'))return;e.preventDefault();e.stopImmediatePropagation();if(el.disabled)return;const act=el.dataset.act;
 if(act==='scene-go'){sceneGo(el.dataset.page);return;}if(act==='scene-resource'){sceneOpenResource(el.dataset.resource);return;}if(act==='scene-pool'){sceneOpenResource('pool');return;}
 if(act==='scene-voice'){sceneStartVoice();return;}
 if(act==='scene-topic'){window.XDPVoice?.cancel();const t=SCENE.tea;if(t.topic===el.dataset.topic)return;t.topics=t.topics||{};t.topics[t.topic]={messages:t.messages,summary:t.summary,saved:t.saved,draft:t.draft,link:t.link,exampleStep:t.exampleStep||0};t.topic=el.dataset.topic;Object.assign(t,t.topics[t.topic]||{messages:[TeaScripts.opening(t.topic)],summary:null,saved:null,draft:'',link:'',exampleStep:0});t.revision++;SCENE.textConsent=false;paintScene();}
 if(act==='scene-ai-template'){const template=STUDIO_POSTERS.find(x=>x.posterKey===el.dataset.key);if(template){openSubmit('tpl');S.submit.tpl=template.id;paintSubmit();}}
 if(act==='scene-script-next'){SCENE.tea.exampleStep=Math.min((SCENE.tea.exampleStep||0)+1,TeaScripts.scenario(SCENE.tea.topic).turns.length);paintScene();}
 if(act==='scene-script-reset'){SCENE.tea.exampleStep=0;paintScene();}
 if(act==='scene-script-prompt'){SCENE.tea.draft=TeaScripts.scenario(SCENE.tea.topic).prompts[Number(el.dataset.i)]||'';const input=$('#scene-tea-draft');if(input){input.value=SCENE.tea.draft;input.focus();}sceneSync();}
 if(act==='scene-script-action'){if(el.dataset.page==='templates')sceneOpenResource('templates');else{SCENE.look.layout=el.dataset.layout;sceneDirty('look');sceneGo('look');}}
 if(act==='scene-crop-step'||act==='scene-crop-reset'){if(!sceneHasLookPhoto()||SCENE.look.loading){SCENE.error='请先选择一张真实图片，才能移动和缩放。';sceneSync();return;}const l=SCENE.look;if(act==='scene-crop-reset'){l.x=50;l.y=50;l.zoom=100;}else{const key=el.dataset.key;l[key]=Math.max(key==='zoom'?50:0,Math.min(key==='zoom'?200:100,l[key]+Number(el.dataset.delta)));}sceneDirty('look');for(const key of ['x','y','zoom']){const input=$('#scene-look-'+key),out=$('#scene-value-'+key);if(input)input.value=l[key];if(out)out.textContent=l[key]+(key==='zoom'?'%':'');}sceneUpdatePreview('look',true);}
 if(act==='scene-summary')sceneMakeSummary();if(act==='scene-summary-save')sceneSaveSummary();
 if(act==='scene-tip-use'){SCENE.look.layout=el.dataset.layout;sceneDirty('look');sceneGo('look');}
 if(act==='scene-layout'){SCENE.look.layout=el.dataset.layout;sceneDirty('look');paintScene();}
 if(act==='scene-look-save')sceneSaveLook();if(act==='scene-join-save')sceneSaveJoin();
 if(act==='scene-sticker'){SCENE.join.sticker=el.dataset.sticker;sceneDirty('join');document.querySelectorAll('[data-act="scene-sticker"]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));sceneUpdatePreview('join');}
 if(act==='scene-look-ai'){if(!sceneHasLookContent()){SCENE.error='先选择照片或导入素材，助手才能看图。';sceneSync();return;}if(SCENE.engine!=='online'){SCENE.notice='当前为本地引导：可先比较两种版式，未读取或分析图片。';sceneSync();return;}sceneTask(async()=>{const rev=SCENE.look.revision,goal=SCENE.look.goal;const image=await sceneRaster(sceneLookSVG());if(rev!==SCENE.look.revision)throw Error('预览已改变，本次图片没有发送，请再次点击 @AI。');const result=await sceneRequest('look',goal,image);if(rev===SCENE.look.revision)SCENE.look.reply=[result.highlight,result.reply,result.suggestion].filter(Boolean).join('\n');});}
 if(act==='scene-to-decision'){if(SCENE.look.saved){sceneSelectArt(SCENE.look.saved);sceneGo('decision');}}
 if(act==='scene-variable'){if(SCENE.decision.kind!==el.dataset.kind){sceneSelectArt(SCENE.decision.id);SCENE.decision.kind=el.dataset.kind;sceneUpdateDecision();}}
 if(act==='scene-adjust')sceneAdjust(Number(el.dataset.delta));if(act==='scene-reset'){sceneSelectArt(SCENE.decision.id);sceneUpdateDecision();}
 if(act==='scene-compare'){SCENE.decision.view=el.dataset.view;sceneUpdateDecision();}
 if(act==='scene-direction'){if(SCENE.decision.changed){SCENE.decision.bingo=true;sceneUpdateDecision();}}
 if(act==='scene-decision-save')sceneSaveDecision();if(act==='scene-open-remix')openEdit(SCENE.decision.saved||SCENE.decision.id);
 if(act==='scene-download'){const target=el.dataset.target,svg=target==='look'?sceneLookSVG():target==='join'?sceneJoinSVG():SCENE.decision.view==='before'?SCENE.decision.baseSvg:SCENE.decision.svg;if(!svg)return;const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'})),a=document.createElement('a');a.href=url;a.download='xingdongpai-'+target+'.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
},true);
